def build_health_payload() -> Dict[str, object]:
    db_ok = False
    db_error = None
    model_ok = False
    model_error = None
    model_ids: List[str] = []
    settings = default_model_settings()
    chat_slot = settings[MODEL_SLOT_CHAT]
    background_slot = settings[MODEL_SLOT_BACKGROUND]

    try:
        init_db()
        with connect_db() as conn:
            conn.execute("SELECT 1").fetchone()
        db_ok = True
        settings = load_model_settings()
        chat_slot = settings[MODEL_SLOT_CHAT]
        background_slot = settings[MODEL_SLOT_BACKGROUND]
    except Exception as exc:  # pragma: no cover - defensive reporting
        db_error = str(exc)

    try:
        headers = {}
        api_key = model_api_key(chat_slot)
        if api_key and api_key != "EMPTY":
            headers["Authorization"] = f"Bearer {api_key}"
        with model_http_client(chat_slot, timeout=20.0) as client:
            resp = client.get(f"{str(chat_slot.get('base_url') or BASE_URL).rstrip('/')}/models", headers=headers)
            resp.raise_for_status()
            payload = resp.json()
        model_ids = [item.get("id", "") for item in payload.get("data", [])]
        model_ok = str(chat_slot.get("model") or MODEL_NAME) in model_ids
    except Exception as exc:
        model_error = str(exc)

    return {
        "ok": db_ok and model_ok,
        "db_ok": db_ok,
        "db_error": db_error,
        "model_ok": model_ok,
        "model_error": model_error,
        "model_name": chat_slot.get("model", MODEL_NAME),
        "model_display_name": chat_slot.get("display_name", LOCAL_MODEL_DISPLAY_NAME),
        "background_model_name": background_slot.get("model", MODEL_NAME),
        "background_model_display_name": background_slot.get("display_name", LOCAL_MODEL_DISPLAY_NAME),
        "image_model": public_image_model_status(),
        "model_ids": model_ids,
        "base_url": chat_slot.get("base_url", BASE_URL),
        "db_path": str(DB_PATH),
    }


