def enqueue_opening_stream_event(
    output_queue: "queue.Queue[Tuple[str, Dict[str, object]]]",
    cancel_event: threading.Event,
    event_type: str,
    payload: Dict[str, object],
) -> bool:
    while not cancel_event.is_set():
        try:
            output_queue.put((event_type, payload), timeout=0.2)
            return True
        except queue.Full:
            continue
    return False


def run_opening_model_stream(
    output_queue: "queue.Queue[Tuple[str, Dict[str, object]]]",
    cancel_event: threading.Event,
    generation_key: str,
    generation_token: str,
    payload: OpeningStreamPayload,
    model_messages: List[Dict[str, object]],
    current_visitor_ip: str,
) -> None:
    answer_parts: List[str] = []
    stripper = ThinkStripper()
    model_started = time.perf_counter()
    model_name = chat_trace_model_name(model_messages)

    def record_fast_opening_trace(event_type: str, status: str, extra: Optional[Dict[str, object]] = None) -> None:
        trace_payload = {
            "model": model_name,
            "status": status,
            "cached_opening": True,
            "opening_id": payload.opening_id,
            "answer_chars": len("".join(answer_parts)),
            "duration_ms": round((time.perf_counter() - model_started) * 1000, 3),
        }
        if extra:
            trace_payload.update(extra)
        try:
            event_name = "fast_opening_stream_model_call_error" if event_type.endswith("_error") else "fast_opening_stream_model_call"
            record_event(None, event_name, current_visitor_ip, trace_payload)
        except Exception:
            pass

    try:
        for raw_delta in iter_model_deltas(
            model_messages,
            payload.max_tokens,
            payload.temperature,
            payload.top_p,
        ):
            if cancel_event.is_set() or is_generation_cancelled(generation_key, generation_token):
                enqueue_opening_stream_event(
                    output_queue,
                    cancel_event,
                    "stopped",
                    {"content": "".join(answer_parts).strip(), "cached_opening": True},
                )
                record_fast_opening_trace("model_call", "cancelled")
                return
            visible_delta = stripper.feed(raw_delta)
            if not visible_delta:
                continue
            answer_parts.append(visible_delta)
            if not enqueue_opening_stream_event(output_queue, cancel_event, "token", {"content": visible_delta}):
                return

        tail = stripper.flush()
        if tail:
            answer_parts.append(tail)
            if not enqueue_opening_stream_event(output_queue, cancel_event, "token", {"content": tail}):
                return

        answer = "".join(answer_parts).strip()
        _, answer = split_think_text(answer)
        if not answer and not cancel_event.is_set() and not is_generation_cancelled(generation_key, generation_token):
            retry_answer = call_chat_completion_once(
                model_messages,
                payload.max_tokens,
                payload.temperature,
                payload.top_p,
            ).strip()
            if retry_answer:
                answer = retry_answer
                if not enqueue_opening_stream_event(output_queue, cancel_event, "token", {"content": answer}):
                    return
                answer_parts = [answer]
        enqueue_opening_stream_event(
            output_queue,
            cancel_event,
            "done",
            {"content": answer, "cached_opening": True, "opening_id": payload.opening_id},
        )
        record_fast_opening_trace("model_call", "completed")
    except Exception as exc:
        record_fast_opening_trace("model_call_error", "error", {"error": str(exc)})
        enqueue_opening_stream_event(output_queue, cancel_event, "error", {"message": f"模型服务调用失败: {exc}"})


@app.post("/api/opening/stream")
async def opening_stream_endpoint(payload: OpeningStreamPayload, request: Request) -> StreamingResponse:
    opening_prompt = payload.opening_prompt.strip()
    if not opening_prompt:
        raise HTTPException(status_code=400, detail="opening_prompt is empty")

    generation_key = opening_generation_key(request)
    request_generation_cancel(generation_key)
    generation_token = acquire_generation_token(generation_key)
    if not generation_token:
        raise HTTPException(status_code=409, detail="an opening response is already generating")
    current_visitor = visitor_ip(request)

    model_messages = [
        {"role": "system", "content": cached_opening_fast_system_prompt()},
        {"role": "user", "content": opening_prompt},
    ]

    async def generate() -> AsyncGenerator[str, None]:
        output_queue: "queue.Queue[Tuple[str, Dict[str, object]]]" = queue.Queue(maxsize=32)
        cancel_event = threading.Event()
        worker = threading.Thread(
            target=run_opening_model_stream,
            args=(output_queue, cancel_event, generation_key, generation_token, payload, model_messages, current_visitor),
            name=f"opening-stream-{generation_token[:8]}",
            daemon=True,
        )
        worker.start()
        try:
            yield format_sse("start", {"opening_id": payload.opening_id, "cached_opening": True})
            while True:
                if await request.is_disconnected():
                    request_generation_cancel(generation_key)
                    return
                if is_generation_cancelled(generation_key, generation_token):
                    yield format_sse("stopped", {"content": "", "cached_opening": True})
                    return
                try:
                    event_type, event_payload = output_queue.get_nowait()
                except queue.Empty:
                    await asyncio.sleep(0.05)
                    continue
                yield format_sse(event_type, event_payload)
                if event_type in {"done", "stopped", "error"}:
                    return
        except asyncio.CancelledError:
            request_generation_cancel(generation_key)
            raise
        finally:
            cancel_event.set()
            release_generation_token(generation_key, generation_token)

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


