@app.post("/api/chat/stream")
def chat_stream(payload: ChatPayload, request: Request) -> StreamingResponse:
    global LAST_USER_ACTIVITY_AT
    init_db()
    session_id = payload.session_id
    message = payload.message.strip()
    cached_opening = bool(payload.cached_opening)
    quoted_message = payload.quoted_message.strip()
    model_message = message
    if quoted_message and not payload.hidden_user and not cached_opening:
        model_message = (
            "用户这轮消息是在回应前文中被引用的内容。请优先围绕引用内容理解指代关系，"
            "不要把引用误认为用户新说的话。\n\n"
            f"【被引用内容】\n{quoted_message}\n\n"
            f"【用户当前消息】\n{message}"
        )
    if not message:
        raise HTTPException(status_code=400, detail="message is empty")

    ensure_active_session(session_id)
    request_tutorial_id = tutorial_request_id(request)
    payload_tutorial_id = normalize_tutorial_id(payload.tutorial_id) if payload.tutorial_mode else ""
    if payload.tutorial_mode:
        if (
            not request_tutorial_id
            or request_tutorial_id != payload_tutorial_id
            or not tutorial_session_matches(payload_tutorial_id, session_id, visitor_ip(request))
        ):
            raise HTTPException(status_code=403, detail="tutorial session does not match")
    if payload.analysis_mode:
        analysis_user_id = require_analysis_user(request)
        if not shared_user_owns_session(analysis_user_id, session_id):
            raise HTTPException(status_code=404, detail="session not found")

    ip = visitor_ip(request)
    refresh_session_visitor_ip(session_id, ip, user_agent(request))
    if should_rate_limit_chat_payload(payload):
        rate_limit = check_chat_device_rate_limit(ip)
        if not rate_limit["allowed"]:
            raise_rate_limited(session_id, ip, message, float(rate_limit["retry_after"]), request)

    LAST_USER_ACTIVITY_AT = time.time()
    interrupt_memory_agent_for_user_input()
    interrupt_idle_agent_for_user_input()
    generation_token = acquire_generation_token(session_id)
    if not generation_token:
        raise HTTPException(status_code=409, detail="a response is already generating")

    record_event(
        session_id,
        "access_chat_start",
        ip,
        {
            "chars": len(message),
            "message_preview": message[:80],
            "attachments": len(payload.attachments),
            "web_search": bool(payload.web_search),
            "mode": payload.mode,
            "analysis_mode": bool(payload.analysis_mode),
            "tutorial_mode": bool(payload.tutorial_mode),
            "cached_opening": cached_opening,
            "hidden_user": bool(payload.hidden_user),
            "quoted_chars": len(quoted_message),
            "client_timing": dict(payload.client_timing or {}),
        },
    )
    analysis_trace_id = str(uuid.uuid4()) if payload.analysis_mode else ""
    user_message_id = add_message(
        session_id,
        "user",
        message,
        attachments=payload.attachments,
        hidden=bool(payload.hidden_user),
        extra_metadata={
            **({"opening_turn": True} if cached_opening else {}),
            **({"quoted_message": quoted_message} if quoted_message and not payload.hidden_user and not cached_opening else {}),
        } or None,
    )
    record_event(
        session_id,
        "message_user",
        ip,
        {
            "chars": len(message),
            "attachments": len(payload.attachments),
            "web_search": bool(payload.web_search),
            "mode": payload.mode,
            "analysis_mode": bool(payload.analysis_mode),
            "cached_opening": cached_opening,
            "quoted_chars": len(quoted_message),
        },
    )
    if analysis_trace_id:
        record_analysis_trace(
            session_id=session_id,
            trace_id=analysis_trace_id,
            event_type="request",
            visitor_ip=ip,
            step_name="cached_opening_start" if cached_opening else "analysis_chat_start",
            payload={
                "visitor_ip": ip,
                "user_agent": user_agent(request),
                "message": message,
                "quoted_message": quoted_message[:2000],
                "attachments": [
                    {
                        "name": attachment.name,
                        "mime_type": attachment.mime_type,
                        "size": attachment.size,
                    }
                    for attachment in payload.attachments
                ],
                "web_search": bool(payload.web_search),
                "mode": payload.mode,
                "cached_opening": cached_opening,
                "temperature": payload.temperature,
                "top_p": payload.top_p,
                "max_tokens": payload.max_tokens,
            },
        )

    tomorrow_clarification = ""
    if not payload.hidden_user and not payload.tutorial_mode:
        tomorrow_clarification = late_night_tomorrow_clarification(
            message,
            already_prompted=session_has_late_night_tomorrow_clarification(session_id),
        )

    def generate() -> Generator[str, None, None]:
        answer_parts: List[str] = []
        stripper = ThinkStripper()
        queued_memory_job = False

        def record_non_analysis_chat_model_call(
            event_type: str,
            status: str,
            started_at: float,
            model_messages_for_trace: List[Dict[str, object]],
            extra: Optional[Dict[str, object]] = None,
        ) -> None:
            if analysis_trace_id:
                return
            trace_payload = {
                "model": chat_trace_model_name(model_messages_for_trace),
                "status": status,
                "answer_chars": len("".join(answer_parts)),
                "duration_ms": round((time.perf_counter() - started_at) * 1000, 3),
                "cached_opening": cached_opening,
                "hidden_user": bool(payload.hidden_user),
            }
            if extra:
                trace_payload.update(extra)
            try:
                event_name = "main_chat_stream_model_call_error" if event_type.endswith("_error") else "main_chat_stream_model_call"
                record_event(session_id, event_name, ip, trace_payload)
            except Exception:
                pass

        try:
            yield format_sse("start", {"session_id": session_id})
            if str(payload.mode or "chat").strip().lower() == "draw":
                status = public_image_model_status()
                if not status.get("available"):
                    message_text = "图像生成模型未配置或不可用，无法生成图片"
                    assistant_id = add_message(session_id, "assistant", message_text, status="failed")
                    record_event(
                        session_id,
                        "draw_generation_unavailable",
                        ip,
                        {"status": status, "user_message_id": user_message_id},
                    )
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="draw_error",
                            visitor_ip=ip,
                            step_name="draw_model_unavailable",
                            payload={"status": status, "message": message_text},
                        )
                    yield format_sse("draw_error", {"message": message_text, "status": status})
                    yield format_sse("done", {"message_id": assistant_id, "content": message_text})
                    return

                yield format_sse("draw_status", {"stage": "prompt", "message": "画图 prompt 优化中"})
                prompt_started = time.perf_counter()
                draw_planner_context_messages = load_recent_planner_context_messages(
                    session_id,
                    limit=MEMORY_PLANNER_CONTEXT_MESSAGES,
                )
                yield format_sse(
                    "memory",
                    {
                        "status": "checking",
                        "stage": "draw_gate",
                        "message": "判断画图是否需要参考记忆...",
                    },
                )
                draw_memory_debug = build_draw_memory_context(
                    message,
                    session_id=session_id,
                    visitor_ip=ip,
                    analysis_trace_id=analysis_trace_id,
                    context_messages=draw_planner_context_messages,
                )
                if draw_memory_debug.get("memory_gate") == "run":
                    selected_count = int(draw_memory_debug.get("selected_count") or 0)
                    candidate_count = int(draw_memory_debug.get("candidate_count") or 0)
                    yield format_sse(
                        "memory",
                        {
                            "status": "done",
                            "stage": "draw_memory",
                            "candidate_count": candidate_count,
                            "selected_count": selected_count,
                            "message": f"画图参考记忆：候选 {candidate_count} 条，选中 {selected_count} 条",
                        },
                    )
                else:
                    yield format_sse(
                        "memory",
                        {
                            "status": "skipped",
                            "stage": "draw_memory",
                            "candidate_count": 0,
                            "selected_count": 0,
                            "message": "画图无需参考记忆",
                        },
                )
                draw_context_parts = [
                    build_draw_prompt_context(session_id, current_message_id=user_message_id),
                    str(draw_memory_debug.get("context") or "").strip(),
                ]
                draw_reference_debug: Dict[str, object] = {"reference_count": 0, "context": "", "refs_b64": []}
                if payload.attachments:
                    yield format_sse(
                        "draw_status",
                        {"stage": "reference", "message": "参考图解析中"},
                    )
                    draw_reference_debug = build_draw_reference_image_context(
                        message,
                        payload.attachments,
                        session_id=session_id,
                        visitor_ip=ip,
                        analysis_trace_id=analysis_trace_id,
                    )
                    reference_count = int(draw_reference_debug.get("reference_count") or 0)
                    if reference_count:
                        yield format_sse(
                            "draw_status",
                            {
                                "stage": "reference",
                                "message": f"已解析 {reference_count} 张参考图",
                            },
                        )
                    elif draw_reference_debug.get("error"):
                        yield format_sse(
                            "draw_status",
                            {"stage": "reference", "message": "参考图解析失败，继续使用文字 prompt"},
                        )
                draw_context_parts.insert(0, str(draw_reference_debug.get("context") or "").strip())
                draw_context = "\n\n".join(part for part in draw_context_parts if part)
                decision = optimize_draw_prompt(
                    message,
                    context=draw_context,
                    session_id=session_id,
                    visitor_ip=ip,
                    analysis_trace_id=analysis_trace_id,
                )
                if analysis_trace_id:
                    record_analysis_trace(
                        session_id=session_id,
                        trace_id=analysis_trace_id,
                        event_type="draw_prompt",
                        visitor_ip=ip,
                        step_name="draw_prompt_optimize",
                        duration_ms=round((time.perf_counter() - prompt_started) * 1000, 3),
                        payload={
                            "decision_summary": {
                                "optimized_prompt_chars": len(str(decision.get("optimized_prompt") or "")),
                                "optimized_prompt_preview": compact_idle_artifact_content(str(decision.get("optimized_prompt") or ""), 160),
                                "negative_prompt": decision.get("negative_prompt", ""),
                                "aspect_ratio": decision.get("aspect_ratio", "1:1"),
                                "image_count": decision.get("image_count", CHAT_DRAW_IMAGE_COUNT),
                                "short_caption": decision.get("short_caption", ""),
                            },
                            "context_chars": len(draw_context),
                            "has_draw_context": bool(draw_context),
                            "memory_debug": {
                                "memory_gate": draw_memory_debug.get("memory_gate"),
                                "candidate_count": draw_memory_debug.get("candidate_count"),
                                "selected_count": draw_memory_debug.get("selected_count"),
                                "retrieval_query": draw_memory_debug.get("retrieval_query"),
                                "error": draw_memory_debug.get("error"),
                            },
                            "reference_debug": {
                                "reference_count": draw_reference_debug.get("reference_count"),
                                "has_reference_prompt": bool(draw_reference_debug.get("reference_prompt")),
                                "error": draw_reference_debug.get("error"),
                            },
                        },
                    )
                yield format_sse(
                    "draw_prompt",
                    {
                        "optimized_prompt": decision.get("optimized_prompt", message),
                        "negative_prompt": decision.get("negative_prompt", ""),
                        "aspect_ratio": decision.get("aspect_ratio", "1:1"),
                        "image_count": CHAT_DRAW_IMAGE_COUNT,
                        "short_caption": decision.get("short_caption", ""),
                    },
                )
                yield format_sse("draw_status", {"stage": "generating", "message": "HiDream 生成中"})
                draw_started = time.perf_counter()
                try:
                    batch = generate_image_batch(
                        original_prompt=message,
                        decision=decision,
                        source_type="chat",
                        source_id=session_id,
                        count=CHAT_DRAW_IMAGE_COUNT,
                        reference_images_b64=draw_reference_debug.get("refs_b64") if isinstance(draw_reference_debug.get("refs_b64"), list) else [],
                    )
                except Exception as exc:
                    message_text = f"图片生成失败: {exc}"
                    assistant_id = add_message(session_id, "assistant", message_text, status="failed")
                    record_event(
                        session_id,
                        "draw_generation_error",
                        ip,
                        {"error": str(exc), "user_message_id": user_message_id},
                    )
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="draw_error",
                            visitor_ip=ip,
                            step_name="draw_image_generation",
                            duration_ms=round((time.perf_counter() - draw_started) * 1000, 3),
                            payload={"error": str(exc), "decision": decision},
                        )
                    yield format_sse("draw_error", {"message": message_text})
                    yield format_sse("done", {"message_id": assistant_id, "content": message_text})
                    return

                images = batch.get("images") if isinstance(batch.get("images"), list) else []
                answer = f"已生成 {len(images)} 张图片。"
                assistant_id = add_message(
                    session_id,
                    "assistant",
                    answer,
                    extra_metadata={
                        "draw": {
                            "batch_id": batch.get("batch_id", ""),
                            "images": images,
                            "optimized_prompt": batch.get("optimized_prompt", ""),
                            "negative_prompt": batch.get("negative_prompt", ""),
                            "aspect_ratio": batch.get("aspect_ratio", "1:1"),
                            "model_name": batch.get("model_name", ""),
                        }
                    },
                )
                record_event(
                    session_id,
                    "draw_generation_completed",
                    ip,
                    {
                        "batch_id": batch.get("batch_id", ""),
                        "image_count": len(images),
                        "user_message_id": user_message_id,
                        "assistant_message_id": assistant_id,
                    },
                )
                if analysis_trace_id:
                    record_analysis_trace(
                        session_id=session_id,
                        trace_id=analysis_trace_id,
                        event_type="draw_image_batch",
                        visitor_ip=ip,
                        step_name="draw_image_generation",
                        duration_ms=round((time.perf_counter() - draw_started) * 1000, 3),
                        payload={"batch": batch, "image_count": len(images)},
                    )
                yield format_sse("draw_image_batch", batch)
                yield format_sse("done", {"message_id": assistant_id, "content": answer})
                return
            if tomorrow_clarification:
                yield format_sse("token", {"content": tomorrow_clarification})
                assistant_id = add_message(session_id, "assistant", tomorrow_clarification)
                record_event(
                    session_id,
                    "late_night_tomorrow_clarification",
                    ip,
                    {"user_message_id": user_message_id, "assistant_message_id": assistant_id},
                )
                if analysis_trace_id:
                    record_analysis_trace(
                        session_id=session_id,
                        trace_id=analysis_trace_id,
                        event_type="guardrail",
                        visitor_ip=ip,
                        step_name="late_night_tomorrow_clarification",
                        payload={"message": message, "answer": tomorrow_clarification},
                    )
                yield format_sse("done", {"message_id": assistant_id, "content": tomorrow_clarification})
                return
            web_search_context = ""
            web_search_sources: List[Dict[str, Any]] = []
            if payload.web_search:
                try:
                    search_context_messages = load_recent_search_planner_messages(session_id)
                    planner_messages = [
                        {"role": "system", "content": SEARCH_PLANNER_SYSTEM_PROMPT},
                        {
                            "role": "user",
                            "content": build_search_planner_user_prompt(
                                message,
                                context_messages=search_context_messages,
                            ),
                        },
                    ]
                    search_plan_started = time.perf_counter()
                    search_plan = build_search_plan(message, context_messages=search_context_messages)
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="model_call",
                            visitor_ip=ip,
                            step_name="search_planner",
                            duration_ms=round((time.perf_counter() - search_plan_started) * 1000, 3),
                            payload={
                                "model": model_slot_config(MODEL_SLOT_BACKGROUND).get("model", MODEL_NAME),
                                "messages": planner_messages,
                                "result": search_plan,
                            },
                        )
                    query_preview = search_plan_display_query(search_plan, message)
                    yield format_sse(
                        "search",
                        {
                            "status": "query",
                            "stage": "routing",
                            "query": query_preview,
                            "route": "llm_planned_search",
                        },
                    )
                    yield format_sse(
                        "search",
                        {
                            "status": "searching",
                            "stage": "searching",
                            "query": query_preview,
                            "searchTarget": "https://duckduckgo.com/html/",
                        },
                    )
                    web_search_started = time.perf_counter()
                    search_results = perform_web_search(
                        message,
                        max_results=WEB_SEARCH_MAX_CANDIDATES,
                        proxy=payload.web_search_proxy,
                        search_plan=search_plan,
                    )
                    search_results = assign_source_registry(search_results)
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="web_search",
                            visitor_ip=ip,
                            step_name="search_candidates",
                            duration_ms=round((time.perf_counter() - web_search_started) * 1000, 3),
                            payload={
                                "query": query_preview,
                                "proxy": normalize_web_search_proxy(payload.web_search_proxy) or "",
                                "count": len(search_results),
                                "results": search_results,
                            },
                        )
                    yield format_sse(
                        "search",
                        {
                            "status": "candidates",
                            "stage": "searching",
                            "result_count": len(search_results),
                            "results": search_results[:WEB_SEARCH_MAX_CANDIDATES],
                        },
                    )
                    enriched_results: List[Dict[str, Any]] = []
                    reliable_candidates = [item for item in search_results if item.get("used_in_answer")]
                    readable_results = (reliable_candidates or search_results[:3])[:WEB_SEARCH_MAX_READ_PAGES]
                    max_pages = len(readable_results)
                    for index, item in enumerate(readable_results, start=1):
                        enriched = dict(item)
                        yield format_sse(
                            "search",
                            {
                                "status": "reading",
                                "stage": "reading",
                                "current_index": index,
                                "max_pages": max_pages,
                                "title": item.get("title", ""),
                                "url": item.get("url", ""),
                                "source_title": item.get("title", ""),
                                "source_url": item.get("url", ""),
                                "confidence": item.get("confidence", 0),
                            },
                        )
                        if item.get("source_type") == "hot_search":
                            yield format_sse(
                                "search",
                                {
                                    "status": "page_done",
                                    "stage": "reading",
                                    "current_index": index,
                                    "max_pages": max_pages,
                                    "title": item.get("title", ""),
                                    "url": item.get("url", ""),
                                    "source_title": item.get("title", ""),
                                    "source_url": item.get("url", ""),
                                    "confidence": item.get("confidence", 0),
                                    "excerpt": item.get("page_excerpt", ""),
                                },
                            )
                            enriched_results.append(enriched)
                            continue
                        try:
                            page_started = time.perf_counter()
                            page_summary = fetch_web_page_summary(
                                item.get("url", ""),
                                proxy=payload.web_search_proxy,
                            )
                            enriched.update(page_summary)
                            enriched["relevance"] = search_result_relevance(
                                enriched,
                                " ".join(
                                    str(term)
                                    for term in (
                                        [message, item.get("planned_query", "")]
                                        + list(item.get("required_terms", []) or [])
                                    )
                                    if term
                                ),
                            )
                            enriched["confidence"] = source_confidence(enriched)
                            yield format_sse(
                                "search",
                                {
                                    "status": "page_done",
                                    "stage": "reading",
                                    "current_index": index,
                                    "max_pages": max_pages,
                                    "title": item.get("title", ""),
                                    "url": item.get("url", ""),
                                    "source_title": item.get("title", ""),
                                    "source_url": item.get("url", ""),
                                    "confidence": enriched.get("confidence", 0),
                                    "relevance": enriched.get("relevance", 0),
                                    "excerpt": page_summary.get("page_excerpt", ""),
                                },
                            )
                            if analysis_trace_id:
                                record_analysis_trace(
                                    session_id=session_id,
                                    trace_id=analysis_trace_id,
                                    event_type="web_page",
                                    visitor_ip=ip,
                                    step_name=f"read_page_{index}",
                                    duration_ms=round((time.perf_counter() - page_started) * 1000, 3),
                                    payload={
                                        "index": index,
                                        "max_pages": max_pages,
                                        "source": item,
                                        "page": page_summary,
                                        "relevance": enriched.get("relevance", 0),
                                        "confidence": enriched.get("confidence", 0),
                                    },
                                )
                        except Exception as exc:
                            yield format_sse(
                                "search",
                                {
                                    "status": "page_error",
                                    "stage": "reading",
                                    "current_index": index,
                                    "max_pages": max_pages,
                                    "title": item.get("title", ""),
                                    "url": item.get("url", ""),
                                    "source_title": item.get("title", ""),
                                    "source_url": item.get("url", ""),
                                    "confidence": item.get("confidence", 0),
                                    "message": str(exc),
                                },
                            )
                            if analysis_trace_id:
                                record_analysis_trace(
                                    session_id=session_id,
                                    trace_id=analysis_trace_id,
                                    event_type="web_page_error",
                                    visitor_ip=ip,
                                    step_name=f"read_page_{index}",
                                    payload={
                                        "index": index,
                                        "source": item,
                                        "error": str(exc),
                                    },
                                )
                        enriched_results.append(enriched)
                    if len(search_results) > len(enriched_results):
                        enriched_results.extend(search_results[len(enriched_results):])
                    search_results = assign_source_registry(enriched_results)
                    web_search_sources = search_results
                    web_search_context = format_web_search_context(search_results)
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="web_search",
                            visitor_ip=ip,
                            step_name="search_context",
                            payload={
                                "sources": search_results,
                                "context": web_search_context,
                            },
                        )
                    yield format_sse(
                        "search",
                        {
                            "status": "verified",
                            "stage": "verified",
                            "result_count": len(search_results),
                            "reliable_count": len(
                                [
                                    item
                                    for item in search_results
                                    if item.get("used_in_answer")
                                ]
                            ),
                        },
                    )
                    record_event(
                        session_id,
                        "web_search_completed",
                        ip,
                        {
                            "query_chars": len(message),
                            "result_count": len(search_results),
                            "proxy": normalize_web_search_proxy(payload.web_search_proxy) or "",
                        },
                    )
                    yield format_sse(
                        "search",
                        {"status": "done", "stage": "done", "result_count": len(search_results)},
                    )
                except Exception as exc:
                    record_event(session_id, "web_search_error", ip, {"error": str(exc)})
                    web_search_context = (
                        "联网搜索参考：本轮已尝试联网搜索，但搜索请求失败。"
                        "回答时请明确说明外部搜索不可用，不要伪造最新资料。"
                    )
                    yield format_sse("search", {"status": "error", "stage": "done", "message": str(exc)})

            if cached_opening:
                system_prompt = cached_opening_system_prompt(ip)
                model_messages = [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": message},
                ]
            else:
                memory_debug: Dict[str, object] = {}
                precomputed_memory_gate: Optional[Dict[str, object]] = None
                memory_planner_context_messages: Optional[List[Dict[str, str]]] = None
                if not payload.web_search:
                    memory_planner_context_messages = load_recent_planner_context_messages(
                        session_id,
                        limit=MEMORY_PLANNER_CONTEXT_MESSAGES,
                    )
                    yield format_sse(
                        "memory",
                        {
                            "status": "checking",
                            "stage": "gate",
                            "message": "判断是否需要回忆...",
                        },
                    )
                    precomputed_memory_gate = resolve_memory_gate_decision(
                        model_message,
                        session_id=session_id,
                        visitor_ip=ip,
                        analysis_trace_id=analysis_trace_id,
                        context_messages=memory_planner_context_messages,
                    )
                    memory_debug["memory_gate"] = (
                        "run" if precomputed_memory_gate.get("needs_memory") else "skipped"
                    )
                    memory_debug["self_profile"] = (
                        "run" if precomputed_memory_gate.get("needs_self_profile") else "skipped"
                    )
                if not payload.web_search and precomputed_memory_gate and precomputed_memory_gate.get("needs_memory"):
                    yield format_sse(
                        "memory",
                        {
                            "status": "running",
                            "stage": "recalling",
                            "message": "正在回忆：生成检索词并读取相关记忆...",
                        },
                    )
                elif (
                    not payload.web_search
                    and precomputed_memory_gate
                    and precomputed_memory_gate.get("needs_self_profile")
                ):
                    yield format_sse(
                        "memory",
                        {
                            "status": "skipped",
                            "stage": "system_profile",
                            "candidate_count": 0,
                            "selected_count": 0,
                            "message": "调用系统资料，直接生成",
                        },
                    )
                elif not payload.web_search:
                    yield format_sse(
                        "memory",
                        {
                            "status": "skipped",
                            "stage": "done",
                            "candidate_count": 0,
                            "selected_count": 0,
                            "message": "无需回忆，直接生成",
                        },
                    )
                system_prompt = build_system_prompt(
                    session_id,
                    model_message,
                    ip,
                    web_search_context=web_search_context,
                    analysis_trace_id=analysis_trace_id,
                    memory_debug=memory_debug,
                    precomputed_memory_gate=precomputed_memory_gate,
                    planner_context_messages=memory_planner_context_messages,
                )
                if not payload.web_search and precomputed_memory_gate and precomputed_memory_gate.get("needs_memory"):
                    candidate_count = int(memory_debug.get("candidate_count") or 0)
                    selected_count = int(memory_debug.get("selected_count") or 0)
                    if memory_debug.get("error"):
                        memory_message = f"回忆降级：文本检索选中 {selected_count} 条"
                    else:
                        memory_message = f"回忆完成：候选 {candidate_count} 条，选中 {selected_count} 条"
                    yield format_sse(
                        "memory",
                        {
                            "status": "done",
                            "stage": "done",
                            "candidate_count": candidate_count,
                            "selected_count": selected_count,
                            "message": memory_message,
                        },
                    )
                model_messages = [{"role": "system", "content": system_prompt}] + build_model_messages_for_request(
                    session_id=session_id,
                    current_message=message,
                    current_model_message=model_message,
                    attachments=payload.attachments,
                    isolate_history=bool(payload.web_search),
                )
            if analysis_trace_id:
                chat_model_name = chat_trace_model_name(model_messages)
                record_analysis_trace(
                    session_id=session_id,
                    trace_id=analysis_trace_id,
                    event_type="model_prompt",
                    visitor_ip=ip,
                    step_name="main_chat_prompt",
                    payload={
                        "model": chat_model_name,
                        "cached_opening": cached_opening,
                        "messages": model_messages,
                    },
                )
            model_started = time.perf_counter()
            for raw_delta in iter_model_deltas(
                model_messages,
                payload.max_tokens,
                payload.temperature,
                payload.top_p,
            ):
                if is_generation_cancelled(session_id, generation_token):
                    record_event(
                        session_id,
                        "generation_cancelled",
                        ip,
                        {"chars": len("".join(answer_parts))},
                    )
                    yield format_sse("stopped", {"content": "".join(answer_parts).strip()})
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="model_call",
                            visitor_ip=ip,
                            step_name="main_chat_stream",
                            duration_ms=round((time.perf_counter() - model_started) * 1000, 3),
                            payload={
                                "model": chat_trace_model_name(model_messages),
                                "status": "cancelled",
                                "chars": len("".join(answer_parts)),
                            },
                        )
                    else:
                        record_non_analysis_chat_model_call(
                            "model_call",
                            "cancelled",
                            model_started,
                            model_messages,
                        )
                    return
                visible_delta = stripper.feed(raw_delta)
                if not visible_delta:
                    continue
                answer_parts.append(visible_delta)
                yield format_sse("token", {"content": visible_delta})

            tail = stripper.flush()
            if tail:
                answer_parts.append(tail)
                yield format_sse("token", {"content": tail})

            answer = "".join(answer_parts).strip()
            _, answer = split_think_text(answer)
            recovered_from_empty_stream = False
            if not answer.strip():
                retry_started = time.perf_counter()
                try:
                    retry_answer = call_chat_completion_once(
                        model_messages,
                        payload.max_tokens,
                        payload.temperature,
                        payload.top_p,
                    ).strip()
                except Exception as exc:
                    retry_answer = ""
                    record_event(
                        session_id,
                        "chat_empty_stream_retry_error",
                        ip,
                        {"error": str(exc), "cached_opening": cached_opening},
                    )
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="model_call_error",
                            visitor_ip=ip,
                            step_name="main_chat_empty_retry",
                            duration_ms=round((time.perf_counter() - retry_started) * 1000, 3),
                            payload={
                                "model": chat_trace_model_name(model_messages),
                                "error": str(exc),
                                "cached_opening": cached_opening,
                            },
                        )
                if retry_answer:
                    answer = retry_answer
                    recovered_from_empty_stream = True
                    yield format_sse("token", {"content": answer})
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="model_call",
                            visitor_ip=ip,
                            step_name="main_chat_empty_retry",
                            duration_ms=round((time.perf_counter() - retry_started) * 1000, 3),
                            payload={
                                "model": chat_trace_model_name(model_messages),
                                "status": "recovered",
                                "answer_chars": len(answer),
                                "cached_opening": cached_opening,
                            },
                        )
                elif cached_opening:
                    record_event(
                        session_id,
                        "cached_opening_empty_skipped",
                        ip,
                        {"user_message_id": user_message_id},
                    )
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="model_call",
                            visitor_ip=ip,
                            step_name="main_chat_stream",
                            duration_ms=round((time.perf_counter() - model_started) * 1000, 3),
                            payload={
                                "model": chat_trace_model_name(model_messages),
                                "status": "empty_skipped",
                                "answer_chars": 0,
                                "cached_opening": cached_opening,
                            },
                        )
                    yield format_sse("done", {"content": "", "skipped_empty": True, "cached_opening": True})
                    return
                else:
                    message_text = "模型返回了空内容，请重试一次。"
                    assistant_id = add_message(session_id, "assistant", message_text, status="failed")
                    record_event(
                        session_id,
                        "chat_empty_response",
                        ip,
                        {"user_message_id": user_message_id, "assistant_message_id": assistant_id},
                    )
                    if analysis_trace_id:
                        record_analysis_trace(
                            session_id=session_id,
                            trace_id=analysis_trace_id,
                            event_type="model_call_error",
                            visitor_ip=ip,
                            step_name="main_chat_stream",
                            duration_ms=round((time.perf_counter() - model_started) * 1000, 3),
                            payload={
                                "model": chat_trace_model_name(model_messages),
                                "status": "empty_failed",
                                "answer_chars": 0,
                            },
                        )
                    else:
                        record_non_analysis_chat_model_call(
                            "model_call_error",
                            "empty_failed",
                            model_started,
                            model_messages,
                        )
                    yield format_sse("error", {"message": message_text})
                    yield format_sse("done", {"message_id": assistant_id, "content": message_text})
                    return
            if web_search_sources:
                answer_with_sources = append_source_footer_if_missing(answer, web_search_sources)
                footer_delta = answer_with_sources[len(answer):]
                if footer_delta:
                    answer = answer_with_sources
                    yield format_sse("token", {"content": footer_delta})
            assistant_id = add_message(
                session_id,
                "assistant",
                answer,
                extra_metadata={"opening_turn": True} if cached_opening else None,
            )
            if analysis_trace_id:
                record_analysis_trace(
                    session_id=session_id,
                    trace_id=analysis_trace_id,
                    event_type="model_call",
                    visitor_ip=ip,
                    step_name="main_chat_stream",
                    duration_ms=round((time.perf_counter() - model_started) * 1000, 3),
                    payload={
                        "model": chat_trace_model_name(model_messages),
                        "status": "completed",
                        "answer_chars": len(answer),
                        "recovered_from_empty_stream": recovered_from_empty_stream,
                    },
                )
            else:
                record_non_analysis_chat_model_call(
                    "model_call",
                    "completed",
                    model_started,
                    model_messages,
                    {"recovered_from_empty_stream": recovered_from_empty_stream},
                )
            record_event(session_id, "message_assistant", ip, {"chars": len(answer)})
            try:
                if payload.hidden_user or payload.tutorial_mode:
                    yield format_sse("done", {"message_id": assistant_id, "content": answer})
                    return
                try:
                    refresh_binding_scoped_opening_prompts(ip)
                except Exception as exc:
                    record_event(session_id, "opening_cache_refresh_error", ip, {"error": str(exc)})
                job_id = enqueue_memory_agent_job(
                    session_id,
                    user_message_id,
                    assistant_id,
                    "turn_complete",
                )
                record_event(session_id, "memory_agent_job_queued", ip, {"job_id": job_id})
                if analysis_trace_id:
                    record_analysis_trace(
                        session_id=session_id,
                        trace_id=analysis_trace_id,
                        event_type="background_job",
                        visitor_ip=ip,
                        step_name="memory_agent_queued",
                        payload={
                            "job_id": job_id,
                            "start_message_id": user_message_id,
                            "end_message_id": assistant_id,
                        },
                    )
                queued_memory_job = True
                artifact_directive_job_started = maybe_start_artifact_directive_agent_job(
                    session_id=session_id,
                    visitor_ip=ip,
                    user_message=message,
                    source_message_ids=[user_message_id, assistant_id],
                    analysis_trace_id=analysis_trace_id,
                )
                if artifact_directive_job_started:
                    record_event(
                        session_id,
                        "artifact_directive_agent_queued",
                        ip,
                        {"user_message_id": user_message_id, "assistant_message_id": assistant_id},
                    )
            except Exception as exc:
                record_event(session_id, "memory_agent_enqueue_error", ip, {"error": str(exc)})
            yield format_sse("done", {"message_id": assistant_id, "content": answer})
        except Exception as exc:
            message_text = f"模型服务调用失败: {exc}"
            add_message(session_id, "assistant", message_text, status="failed")
            record_event(session_id, "message_error", ip, {"error": str(exc)})
            yield format_sse("error", {"message": message_text})
        finally:
            release_generation_token(session_id, generation_token)
            if queued_memory_job:
                start_memory_agent_worker()

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )

